insert into properties (slug, title, location, price, description, about, image, gallery, beds, baths, sqft, highlight, status, property_type, year_built, lot_size, parking, features, neighborhood_name, neighborhood_city, neighborhood_description, sort_order) values (
  'willowbrook-house', 'Willowbrook House', 'Victoria Island, Lagos', '₦430,000,000', 'A cozy contemporary home just minutes from the waterfront.',
  ARRAY['Willowbrook House sits on a quiet street in Victoria Island, just minutes from the waterfront. The design favors clean lines and comfortable proportions, with natural light reaching every principal room.', 'A compact footprint is used efficiently, with an open-plan living and dining area that flows onto a private courtyard. Bedrooms are arranged for privacy, each with generous storage and en-suite bathrooms.', 'The location offers effortless access to Victoria Island''s offices, restaurants, and waterfront promenades, making it well suited to professionals and small families alike.']::text[],
  'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?q=80&w=1600&auto=format&fit=crop',
  ARRAY['https://images.unsplash.com/photo-1512917774080-9991f1c4c750?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1613977257363-707ba9348227?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1600573472592-401b489a3cdc?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1523217582562-09d0def993a6?q=80&w=1600&auto=format&fit=crop']::text[],
