  4, 5, '3,800', 'Smart Home', 'Available', 'Detached Duplex', 2023, '0.22 Acres', '3-Car Garage',
  ARRAY['Smart lighting and security', 'Open-plan kitchen island', 'Landscaped rear garden', 'Fitted upstairs storage', 'Sliding glass doors', 'Visitor parking bay']::text[],
