) on conflict (slug) do nothing;

insert into properties (slug, title, location, price, description, about, image, gallery, beds, baths, sqft, highlight, status, property_type, year_built, lot_size, parking, features, neighborhood_name, neighborhood_city, neighborhood_description, sort_order) values (
  'bellview-heights', 'Bellview Heights', 'Banana Island, Lagos', '₦1,450,000,000', 'An architectural statement mansion built for large-scale entertaining.',
  ARRAY['Bellview Heights occupies a prime plot on Banana Island, Lagos''s most exclusive address. Bold geometric massing and a striking material palette set the home apart, while the interior scales up to match: soaring ceilings, wide-format stone, and a fireplace-anchored living hall built for hosting.', 'A separate family wing keeps everyday living private from the formal entertaining spaces, and a fully equipped home cinema and study round out the ground floor. Every principal room takes in views over the surrounding island.', 'With round-the-clock estate security and direct access to Banana Island''s private marina facilities, the property suits buyers seeking the very top end of Lagos''s residential market.']::text[],
  'https://images.unsplash.com/photo-1600047509358-9dc75507daeb?q=80&w=1600&auto=format&fit=crop',
  ARRAY['https://images.unsplash.com/photo-1600047509358-9dc75507daeb?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1600121848594-d8644e57abab?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1600210491892-03d54c0aaf87?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1560185008-b033106af5c3?q=80&w=1600&auto=format&fit=crop', 'https://images.unsplash.com/photo-1560185127-6ed189bf02f4?q=80&w=1600&auto=format&fit=crop']::text[],
  6, 8, '8,200', 'Home Cinema', 'Available', 'Luxury Mansion', 2023, '0.6 Acres', '6-Car Garage',
  ARRAY['Home cinema and study', 'Fireplace-anchored living hall', 'Separate family wing', 'Wide-format stone finishes', 'Marina access', 'Round-the-clock estate security']::text[],
  'Banana Island', 'Lagos, Nigeria', 'A man-made, gated island off Ikoyi and Lagos''s most exclusive address, home to ambassadors, executives, and the country''s highest-value real estate.', 5
) on conflict (slug) do nothing;

