-- FAQs
insert into faqs (question, answer, sort_order) values ('What services does DEGSS offer?', 'DEGSS helps clients buy, rent, and manage residential and commercial properties. Our team handles everything from property search and viewings to negotiations, documentation, and after-sale support.', 0);
insert into faqs (question, answer, sort_order) values ('How do I schedule a property viewing?', 'You can book a viewing by reaching out through our Contact page, calling us directly, or clicking "Get started" on any listing. A member of our team will confirm a convenient time with you within 24 hours.', 1);
insert into faqs (question, answer, sort_order) values ('Are the prices on your listings negotiable?', 'Pricing depends on the property and the seller or landlord. Our agents will let you know upfront whether a listing has room for negotiation and will represent your interests through the process.', 2);
insert into faqs (question, answer, sort_order) values ('What documents do I need to rent or buy a property?', 'Requirements vary by property, but you should generally have a valid form of identification, proof of income or funds, and, for rentals, references from a previous landlord or employer. Our team will provide a full checklist once you''ve found a property you''re interested in.', 3);
insert into faqs (question, answer, sort_order) values ('Do you charge a fee for using DEGSS?', 'Browsing listings and booking viewings is free. Agency and legal fees may apply once a transaction proceeds, and these are always communicated clearly before you commit to anything.', 4);
insert into faqs (question, answer, sort_order) values ('Which areas do you cover?', 'We currently operate across Lagos, with a focus on Lekki, Ibeju-Lekki, and surrounding areas. Get in touch if you''re looking outside these areas — we may still be able to help through our partner network.', 5);
insert into faqs (question, answer, sort_order) values ('How long does the buying or renting process take?', 'Rentals can typically close within 1–2 weeks once documentation is complete. Purchases take longer due to legal and title verification, usually ranging from a few weeks to a couple of months depending on the property.', 6);
insert into faqs (question, answer, sort_order) values ('Can DEGSS help manage a property I already own?', 'Yes. Our property management service covers tenant sourcing, rent collection, maintenance coordination, and regular reporting so you can own property without the day-to-day hassle.', 7);

-- Team members
insert into team_members (name, title, photo, bio, sort_order) values ('Daniel Onwuzuka', 'Managing Director', '/team/Daniel.jpeg', 'A business strategist and entrepreneur with extensive experience across sales, marketing, business development and operations. As Managing Director, Daniel provides strategic direction for the organisation, driving growth, strengthening operations and developing high-performing teams. With experience spanning real estate, technology, fashion and emerging business sectors, he combines strategic thinking with hands-on execution to identify opportunities, build scalable systems and create sustainable value for customers, investors and stakeholders.', 0);
insert into team_members (name, title, photo, bio, sort_order) values ('Emmanuel Aiyepada', 'Head, Branding and Corporate Communications', '/team/Emmanuel.jpeg', 'A brand strategist and corporate communications professional with close to a decade of experience across branding, strategic communications, public relations and stakeholder engagement. As Head of Branding and Corporate Communications, Emmanuel drives the organization’s brand positioning, communications and market visibility. His experience spans real estate, technology, oil and gas, public sector and nonprofit sectors, combining strategic thinking, creative execution and leadership development to strengthen brands and drive sustainable growth.', 1);
insert into team_members (name, title, photo, bio, sort_order) values ('Ogbonnaya Chukwu Samuel', 'Head, Operations', '/team/Ogbonnaya.jpeg', 'A real estate professional and strategic business leader with over 17 years of experience across sales, business development, operations and market growth. As Head of Operations, Ogbonnaya drives operational efficiency, team performance and business growth. With expertise spanning real estate, agrochemicals, industrial chemicals and cosmetics, he combines commercial strategy, industry knowledge and people leadership to build high-performing teams and create sustainable value.', 2);
insert into team_members (name, title, photo, bio, sort_order) values ('Godswill Onyegbule', 'Head, IT', '/team/Godswill.jpg', 'A technology professional, real estate consultant and business strategist with over 10 years of experience across technology, sales and property advisory. As Head of IT, Godswill provides strategic direction for the organisation’s technology and digital systems. With a background spanning technology leadership and real estate investment advisory, he combines technical expertise, commercial insight and strategic thinking to improve business processes and help clients make smarter investment decisions.', 3);

